import { SOLAR as BASE_SOLAR } from "@/lib/icons/solar-map";
import { EXTRA_SOLAR } from "@/lib/icons/solar-extra";

const SOLAR = { ...BASE_SOLAR, ...EXTRA_SOLAR };
export type IconName = keyof typeof SOLAR;

// Official Solar icons (@solar-icons/react), same set and styles as the Flutter app:
// filled = SolarIconsBold -> "bold", default = SolarIconsOutline -> "outline".
// The map is generated by scripts/gen-solar-map.mjs. Names mirror Flutter's SolarIcons* members.
//
// weight (outline only): Solar's Outline paths are filled shapes, which read thin at small sizes.
// "medium"/"strong" add a hairline round-joined stroke in the icon's own colour on top of the official
// paths (no path data is edited). "regular" is the untouched official glyph.
const WEIGHT = {
  regular: "",
  medium: "[stroke:currentColor] [stroke-width:0.6px] [stroke-linejoin:round]",
  strong: "[stroke:currentColor] [stroke-width:1px] [stroke-linejoin:round]",
} as const;

export type IconWeight = keyof typeof WEIGHT;

// Multi-colour palette for casual icons (settings rows, info glyphs, state icons).
export const TONES = {
  fire: "#FF5A1F",
  orange: "#FF8A1F",
  amber: "#FFB020",
  gold: "#FFC300",
  sky: "#2EA8FF",
  mint: "#1FC98E",
  violet: "#9B6BFF",
  rose: "#FF4D7D",
  steel: "#8A94A6",
} as const;

// "none" opts out of every automatic colour and of the automatic fill.
export type IconTone = keyof typeof TONES | "none";

// CASUAL icons: coloured AND filled everywhere by default. Main interaction icons (like, share, comment, send,
// close, back, plus, chevrons, search, nav, bell, composer tools, buttons) are deliberately NOT here.
// Auto colour is skipped when the call site already sets a text-* colour, or passes its own tone / filled.
const AUTO: Partial<Record<IconName, keyof typeof TONES>> = {
  fire: "fire",
  stars: "gold",
  star: "gold",
  diploma: "gold",
  letter: "gold",
  gift: "rose",
  calendar: "fire",
  tag: "orange",
  bag: "orange",
  bag2: "orange",
  shop: "orange",
  cart: "orange",
  caseMinimalistic: "orange",
  pointOnMap: "rose",
  pinCircle: "rose",
  pin: "rose",
  forbidden: "rose",
  mapPointSchool: "sky",
  school: "sky",
  earth: "sky",
  squareAcademicCap: "violet",
  book: "violet",
  hashtag: "violet",
  phone: "mint",
  link: "mint",
  linkRound: "mint",
  checkCircle: "mint",
};

const HAS_TEXT_COLOR = /(^|\s)text-/;

export function Icon({
  name,
  className = "size-6",
  filled,
  weight = "medium",
  tone,
}: {
  name: IconName;
  className?: string;
  filled?: boolean;
  weight?: IconWeight;
  tone?: IconTone;
}) {
  const auto = tone === undefined && !HAS_TEXT_COLOR.test(className) ? AUTO[name] : undefined;
  // Casual icons and any icon with an explicit tone are filled unless the call site says otherwise.
  const isFilled = filled ?? (!!auto || (tone !== undefined && tone !== "none"));
  // A filled bookmark is a SAVED bookmark everywhere: always orange/yellow, never the brand purple.
  const effective: IconTone | undefined = tone ?? (name === "bookmark" && isFilled ? "amber" : undefined) ?? auto;
  const color = effective && effective !== "none" ? TONES[effective] : undefined;
  const Glyph = SOLAR[name][isFilled ? "bold" : "outline"];
  const extra = isFilled ? "" : WEIGHT[weight];
  // The wrapper owns the size (className), the glyph fills it. Sizing the glyph itself via size="1em"
  // made every icon follow the parent's font-size and ignore size-* classes.
  return (
    <span
      className={`inline-flex shrink-0 items-center justify-center ${className}`.trim()}
      style={color ? { color } : undefined}
      aria-hidden="true"
    >
      <Glyph className={`size-full ${extra}`.trim()} size="100%" color="currentColor" />
    </span>
  );
}
